export type AccessState =
  | { phase: "closed"; notice: string | null }
  | { phase: "editing"; account: string; secret: string; error: string | null }
  | { phase: "submitting"; account: string; secret: string };

export type AccessEvent =
  | { type: "open" }
  | { type: "cancel" }
  | { type: "changeAccount"; value: string }
  | { type: "changeSecret"; value: string }
  | { type: "submit" }
  | { type: "reply"; message: string };

export function reduceAccessState(state: AccessState, event: AccessEvent): AccessState {
  if (event.type === "cancel" && state.phase !== "closed") {
    return { phase: "closed", notice: null };
  }
  if (event.type === "open" && state.phase === "closed") {
    return { phase: "editing", account: "", secret: "", error: null };
  }
  if (state.phase === "editing") {
    if (event.type === "changeAccount") {
      return { ...state, account: event.value, error: null };
    }
    if (event.type === "changeSecret") {
      return { ...state, secret: event.value, error: null };
    }
    if (event.type === "submit") {
      if (state.account.trim().length === 0 || state.secret.length === 0) {
        return { ...state, error: "Missing credentials" };
      }
      return { phase: "submitting", account: state.account, secret: state.secret };
    }
  }
  if (state.phase === "submitting" && event.type === "reply") {
    return { phase: "closed", notice: "Access granted" };
  }
  return state;
}

