import { reduceAccessState } from "./solution";
import type { AccessEvent, AccessState } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const closed: AccessState = { phase: "closed", notice: "old notice" };
const opened = reduceAccessState(closed, { type: "open" });
equal(opened, { phase: "editing", account: "", secret: "", error: null }, "open creates an empty editing form");
assert(opened !== closed, "applicable event returns a new state");
equal(closed, { phase: "closed", notice: "old notice" }, "open does not mutate closed state");

for (const event of [
  { type: "changeAccount", value: "x" },
  { type: "changeSecret", value: "x" },
  { type: "submit" },
  { type: "reply", message: "operator" },
  { type: "cancel" },
] as AccessEvent[]) {
  assert(reduceAccessState(closed, event) === closed, `${event.type} is inapplicable while closed`);
}

const editing: AccessState = { phase: "editing", account: " old ", secret: "secret", error: "bad" };
const accountEvent: AccessEvent = { type: "changeAccount", value: " new " };
const accountChanged = reduceAccessState(editing, accountEvent);
equal(accountChanged, { phase: "editing", account: " new ", secret: "secret", error: null }, "account change preserves value and clears error");
const secretChanged = reduceAccessState(editing, { type: "changeSecret", value: " next " });
equal(secretChanged, { phase: "editing", account: " old ", secret: " next ", error: null }, "secret change preserves value and clears error");
equal(editing, { phase: "editing", account: " old ", secret: "secret", error: "bad" }, "changes do not mutate state");
equal(accountEvent, { type: "changeAccount", value: " new " }, "change does not mutate event");

const missingAccount: AccessState = { phase: "editing", account: "  ", secret: "secret", error: null };
equal(reduceAccessState(missingAccount, { type: "submit" }), { phase: "editing", account: "  ", secret: "secret", error: "Missing credentials" }, "trimmed-empty account is rejected without changing entered values");
const missingSecret: AccessState = { phase: "editing", account: "alice", secret: "", error: "old" };
equal(reduceAccessState(missingSecret, { type: "submit" }), { phase: "editing", account: "alice", secret: "", error: "Missing credentials" }, "empty secret is rejected");
const whitespaceSecret: AccessState = { phase: "editing", account: " alice ", secret: "   ", error: null };
equal(reduceAccessState(whitespaceSecret, { type: "submit" }), { phase: "submitting", account: " alice ", secret: "   " }, "nonempty whitespace secret is preserved and accepted");

const submitting: AccessState = { phase: "submitting", account: "alice", secret: "pw" };
equal(reduceAccessState(submitting, { type: "reply", message: "operator" }), { phase: "closed", notice: "Access granted" }, "operator reply grants access");
equal(reduceAccessState(submitting, { type: "reply", message: "wrong" }), { phase: "editing", account: "alice", secret: "pw", error: "wrong" }, "non-operator reply returns to editing with its message");
equal(reduceAccessState(submitting, { type: "reply", message: "" }), { phase: "editing", account: "alice", secret: "pw", error: "Access denied" }, "empty reply uses default denial error");
equal(reduceAccessState(submitting, { type: "reply", message: "operator " }), { phase: "editing", account: "alice", secret: "pw", error: "operator " }, "operator comparison is exact");

equal(reduceAccessState(editing, { type: "cancel" }), { phase: "closed", notice: null }, "cancel closes editing");
equal(reduceAccessState(submitting, { type: "cancel" }), { phase: "closed", notice: null }, "cancel closes submitting");
assert(reduceAccessState(editing, { type: "open" }) === editing, "open is inapplicable while editing");
assert(reduceAccessState(editing, { type: "reply", message: "x" }) === editing, "reply is inapplicable while editing");
assert(reduceAccessState(submitting, { type: "submit" }) === submitting, "submit is inapplicable while submitting");
assert(reduceAccessState(submitting, { type: "changeSecret", value: "x" }) === submitting, "changes are inapplicable while submitting");

